\operatorname{inp}(x,b,P)[u:=z]=
\begin{cases}
\operatorname{inp}(x',b,P), & b=u,\\
\operatorname{inp}(x',b,P[u:=z]), & b\ne u,\ b\ne z,\\
\operatorname{inp}(x',w,(P[b:=w])[u:=z]), & b\ne u,\ b=z,
\end{cases}

\operatorname{rep}(x,b,P)[u:=z]=
\begin{cases}
\operatorname{rep}(x',b,P), & b=u,\\
\operatorname{rep}(x',b,P[u:=z]), & b\ne u,\ b\ne z,\\
\operatorname{rep}(x',w,(P[b:=w])[u:=z]), & b\ne u,\ b=z,
\end{cases}
